namespace FileCompass {
 internal static class MediaNamesTests {
  static void Mp3(string path){using(var output=File.Create(path))for(int i=0;i<12;i++){var frame=new byte[417];frame[0]=255;frame[1]=251;frame[2]=144;frame[3]=100;output.Write(frame,0,frame.Length);}}
  static byte[] Pixels(string path){using(var input=File.OpenRead(path)){var decoder=BitmapDecoder.Create(input,BitmapCreateOptions.PreservePixelFormat,BitmapCacheOption.OnLoad);var frame=decoder.Frames[0];int stride=(frame.PixelWidth*frame.Format.BitsPerPixel+7)/8;var pixels=new byte[stride*frame.PixelHeight];frame.CopyPixels(pixels,stride,0);return pixels;}}
  static string Hash(string path){using(var input=File.OpenRead(path))return MediaNames.Hash(input,CancellationToken.None);}
  internal static int Run(string root){Directory.CreateDirectory(root);var checks=new List<string>();MediaNamesWindow window=null;Action<bool,string> check=(ok,label)=>{if(!ok)throw new Exception(label);checks.Add(label);};Action<Action,string> reject=(action,label)=>{bool failed=false;try{action();}catch{failed=true;}check(failed,label);};
   try{System.Threading.SynchronizationContext.SetSynchronizationContext(new DispatcherSynchronizationContext(Dispatcher.CurrentDispatcher));FluentTheme.Ensure();
    check(HelpContent.ContextTopic(typeof(MediaNamesWindow))=="rename","Metadata dialog F1 opens its own help topic");
    var values=MediaNames.Parse("Žluťoučký - 007 - Píseň - live","[MP3.Artist] - [MP3.Track] - [MP3.Title]");check(values["[MP3.Artist]"]=="Žluťoučký"&&values["[MP3.Track]"]=="7"&&values["[MP3.Title]"]=="Píseň - live","Filename parser preserves Unicode, canonicalizes track numbers and retains separators inside final fields");
    reject(()=>MediaNames.Parse("x","[MP3.Unknown]"),"Unknown tokens are rejected");reject(()=>MediaNames.Parse("x","[MP3.Title][MP3.Artist]"),"Adjacent variable fields require an explicit delimiter");reject(()=>MediaNames.Parse("a-a","[Image.Title]-[Image.Title]"),"Duplicate fields are rejected");reject(()=>MediaNames.Parse("0 - song","[MP3.Track] - [MP3.Title]"),"Invalid track numbers are rejected");reject(()=>MediaNames.Parse("2026-02-30","[EXIF.Date]"),"Invalid calendar dates are rejected");check(MediaNames.Parse("prefix - title","[Ignore] - [Image.Title]")["[Image.Title]"]=="title","Ignore token skips a filename segment");
    string music=Path.Combine(root,"Žluťoučký - 007 - Píseň.mp3");Mp3(music);byte[] original=File.ReadAllBytes(music);using(var file=TagLib.File.Create(music)){file.Tag.Album="Existing album";file.Tag.Comment="Keep comment";file.Save();}original=File.ReadAllBytes(music);
    var row=MediaNames.PreviewOne(music,"[MP3.Artist] - [MP3.Track] - [MP3.Title]",false,CancellationToken.None);check(row.Changes!=null&&row.Changes.Count==3,"Preview plans only named missing MP3 fields");check(original.SequenceEqual(File.ReadAllBytes(music)),"Metadata preview leaves source bytes unchanged");MediaNames.Apply(row,CancellationToken.None);check(File.Exists(row.Backup)&&original.SequenceEqual(File.ReadAllBytes(row.Backup)),"Metadata write retains a byte-exact original backup");
    using(var file=TagLib.File.Create(music)){check(file.Tag.Title=="Píseň"&&file.Tag.Track==7&&file.Tag.Performers.Single()=="Žluťoučký","Written ID3 fields roundtrip with Unicode");check(file.Tag.Album=="Existing album"&&file.Tag.Comment=="Keep comment","Unselected album and comment tags survive writing");}
    var afterAudio=File.ReadAllBytes(music);Func<byte[],int> frameStart=bytes=>Enumerable.Range(0,bytes.Length-4).First(i=>bytes[i]==255&&bytes[i+1]==251&&bytes[i+2]==144&&bytes[i+3]==100);check(original.Skip(frameStart(original)).Take(12*417).SequenceEqual(afterAudio.Skip(frameStart(afterAudio)).Take(12*417)),"Writing ID3 metadata preserves all MPEG audio frame bytes");
    var rename=BatchRenameEngine.Preview(new[]{music},new RenameOptions{Name="[MP3.Track] - [MP3.Title]"})[0];check(rename.NewName=="07 - Píseň.mp3","Newly written metadata can generate padded filenames");BatchRenameEngine.Apply(new[]{rename},CancellationToken.None);check(File.Exists(rename.NewPath),"Metadata-based rename applies through the existing collision-checked engine");music=rename.NewPath;
    row=MediaNames.PreviewOne(music,"[MP3.Track] - [MP3.Title]",false,CancellationToken.None);check(row.Changes!=null&&row.Changes.Count==0,"Existing metadata is preserved by default");
    row=MediaNames.PreviewOne(music,"[MP3.Title]",true,CancellationToken.None);check(row.Changes!=null&&row.Changes.Count==1,"Explicit overwrite plans a replacement of existing metadata");File.AppendAllText(music,"changed");string changed=Hash(music);reject(()=>MediaNames.Apply(row,CancellationToken.None),"Changed source files are rejected after preview");check(Hash(music)==changed,"Rejected metadata write preserves the changed source");
    var cancelled=new CancellationToken(true);reject(()=>MediaNames.PreviewOne(music,"[MP3.Title]",false,cancelled),"Preview observes cancellation");
    string image=Path.Combine(root,"2026-10-24_14-30-05 - Výlet.jpg");var bitmap=BitmapSource.Create(8,8,96,96,PixelFormats.Rgb24,null,Enumerable.Range(0,192).Select(x=>(byte)x).ToArray(),24);var encoder=new JpegBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(bitmap));using(var output=File.Create(image))encoder.Save(output);byte[] pixels=Pixels(image);string before=Hash(image);
    row=MediaNames.PreviewOne(image,"[EXIF.Date]_[EXIF.Time] - [Image.Title]",false,CancellationToken.None);check(row.Changes!=null&&row.Changes.Count==3,"Image preview extracts date, time and title");MediaNames.Apply(row,CancellationToken.None);check(row.Backup!=null&&Hash(row.Backup)==before,"JPEG write retains its original backup");check(Pixels(image).SequenceEqual(pixels),"JPEG metadata writing preserves decoded image pixels");
    using(var file=TagLib.File.Create(image)){var tag=(TagLib.Image.CombinedImageTag)file.Tag;check(tag.Title=="Výlet"&&tag.DateTime==new DateTime(2026,10,24,14,30,5),"JPEG title and capture timestamp roundtrip");}
    rename=BatchRenameEngine.Preview(new[]{image},new RenameOptions{Name="[Image.Title]_[EXIF.Date]"})[0];check(rename.NewName=="Výlet_2026-10-24.jpg","Image titles and EXIF values generate filenames");
    row=MediaNames.PreviewOne(image,"[MP3.Title]",false,CancellationToken.None);check(row.Changes==null,"Audio fields are rejected for image files");File.SetAttributes(image,FileAttributes.ReadOnly);row=MediaNames.PreviewOne(image,"[Image.Title]",true,CancellationToken.None);check(row.Changes==null,"Read-only images are reported without changing them");File.SetAttributes(image,FileAttributes.Normal);
    string png=Path.Combine(root,"Český obrázek.png");var pngEncoder=new PngBitmapEncoder();pngEncoder.Frames.Add(BitmapFrame.Create(bitmap));using(var output=File.Create(png))pngEncoder.Save(output);pixels=Pixels(png);row=MediaNames.PreviewOne(png,"[Image.Title]",false,CancellationToken.None);MediaNames.Apply(row,CancellationToken.None);using(var file=TagLib.File.Create(png))check(file.Tag.Title=="Český obrázek","PNG title writing roundtrips");check(Pixels(png).SequenceEqual(pixels),"PNG metadata writing preserves decoded pixels");
    string wav=Path.Combine(root,"Zvuk.wav");using(var output=File.Create(wav))using(var writer=new BinaryWriter(output)){writer.Write(Encoding.ASCII.GetBytes("RIFF"));writer.Write(36+44100);writer.Write(Encoding.ASCII.GetBytes("WAVEfmt "));writer.Write(16);writer.Write((short)1);writer.Write((short)1);writer.Write(44100);writer.Write(44100);writer.Write((short)1);writer.Write((short)8);writer.Write(Encoding.ASCII.GetBytes("data"));writer.Write(44100);writer.Write(new byte[44100]);}row=MediaNames.PreviewOne(wav,"[MP3.Title]",false,CancellationToken.None);MediaNames.Apply(row,CancellationToken.None);using(var audio=TagLib.File.Create(wav))check(audio.Tag.Title=="Zvuk","Audio metadata writing also supports WAV containers");
    string tiff=Path.Combine(root,"Fotografie.tiff");var tiffEncoder=new TiffBitmapEncoder();tiffEncoder.Frames.Add(BitmapFrame.Create(bitmap));using(var output=File.Create(tiff))tiffEncoder.Save(output);pixels=Pixels(tiff);row=MediaNames.PreviewOne(tiff,"[Image.Title]",false,CancellationToken.None);MediaNames.Apply(row,CancellationToken.None);using(var photo=TagLib.File.Create(tiff))check(photo.Tag.Title=="Fotografie","TIFF title metadata writing roundtrips");check(Pixels(tiff).SequenceEqual(pixels),"TIFF metadata writing preserves decoded pixels");
    int activity=0;window=new MediaNamesWindow(null,new[]{png},()=>{},value=>activity+=value?1:-1){Left=-18000,Top=-18000};window.Show();NavigationTests.Wait(window.PreviewTask);check(window.Rows!=null&&activity==0&&!window.WriteButton.IsEnabled,"Native dialog completes preview and disables writing unchanged files");window.Mask.Text="[Ignore] - [Image.Title]";check(window.Rows==null&&!window.WriteButton.IsEnabled,"Changing the mask invalidates the previous preview");check(window.Width>=Math.Min(1300,window.MaxWidth),"Metadata writer opens at a wider work-area-bounded size");var tokens=(System.Windows.Controls.ContextMenu)window.Mask.GetValue(TokenDropdown.MenuProperty);check(tokens!=null&&tokens.Items.Count==MediaNames.WritableTokens.Length+1,"Filename-to-metadata dropdown offers only writable fields and Ignore");window.Mask.Text="abXXcd";window.Mask.Select(2,2);window.Mask.RaiseEvent(new System.Windows.Input.MouseButtonEventArgs(System.Windows.Input.Mouse.PrimaryDevice,Environment.TickCount,System.Windows.Input.MouseButton.Left){RoutedEvent=UIElement.PreviewMouseLeftButtonUpEvent});check(tokens.IsOpen,"Clicking the mask field opens the token dropdown");((System.Windows.Controls.MenuItem)tokens.Items.Cast<object>().OfType<System.Windows.Controls.MenuItem>().Single(x=>Convert.ToString(x.Tag)=="[Image.Title]")).RaiseEvent(new RoutedEventArgs(System.Windows.Controls.MenuItem.ClickEvent));check(window.Mask.Text=="ab[Image.Title]cd"&&window.Mask.CaretIndex==2+"[Image.Title]".Length,"Choosing a token replaces only the current selection and restores the caret");tokens.IsOpen=false;NextStageTests.Draw(window,Path.Combine(root,"wide-metadata-writer.png"));window.Close();window=null;var renameWindow=new BatchRenameWindow(null,new[]{png},delegate{}){Left=-18000,Top=-18000};renameWindow.Show();NavigationTests.Wait(renameWindow.PreviewTask);var renameInput=FluentUiTests.Children<System.Windows.Controls.TextBox>(renameWindow).Single(x=>x.GetValue(TokenDropdown.MenuProperty)!=null);var renameTokens=(System.Windows.Controls.ContextMenu)renameInput.GetValue(TokenDropdown.MenuProperty);check(renameWindow.Width>=Math.Min(1300,renameWindow.MaxWidth),"Metadata-to-filename dialog opens at a wider bounded size");check(renameTokens.Items.Cast<object>().OfType<System.Windows.Controls.MenuItem>().Any(x=>Convert.ToString(x.Tag)=="[File.Created]")&&renameTokens.Items.Cast<object>().OfType<System.Windows.Controls.MenuItem>().Any(x=>Convert.ToString(x.Tag)=="[MP3.Title]"),"Rename dropdown includes filesystem dates and media metadata");NextStageTests.Draw(renameWindow,Path.Combine(root,"wide-metadata-renamer.png"));renameWindow.Close();
    File.WriteAllLines(Path.Combine(root,"result.txt"),checks.Concat(new[]{"PASS: "+checks.Count+" checks"}));return 0;
   }catch(Exception ex){File.WriteAllText(Path.Combine(root,"result.txt"),"FAIL after "+checks.Count+" checks\n"+String.Join("\n",checks)+"\n"+ex);return 1;}finally{if(window!=null)window.Close();}
  }
 }
}
